import numpy as np
def fit(deg):
    cols=[];names=[]
    for i in range(deg+1):
        for j in range(deg+1-i):
            cols.append(t**i*A**j); names.append((i,j))
    X=np.column_stack(cols)
    c=np.linalg.lstsq(X,dA_dt,rcond=None)[0]
    r=dA_dt-X@c
    return np.mean(r**2)/np.var(dA_dt), names, c
